#include "ordinary_multi_continuation.hpp"
#include "ordinary_predefined_validation.hpp"
#include <iostream>
#include <set>

namespace {
size_t checks=0,cases=0,boards=0,placements=0,preserved=0;
void check(bool ok,const char *message){++checks;if(!ok)throw std::runtime_error(message);}
study::OrdinaryPredefinedRecord manual(size_t group,size_t ordinal,study::Point position,double angle=0,bool flip=false){return {group,ordinal,{1000+100*group+ordinal,position,{int32_t(flip),angle,angle},2}};}
study::ReverseRunnerFactory offset(){return [](const study::Input &input)->study::ReverseRunner{const auto program=study::offsetProgram(input);return [program](const auto &source,auto &time,auto &state){return study::ordinaryOffsetContinue(source,program,time,state);};};}
void native(const study::OrdinaryMultiPredefinedScene &scene){std::set<uintptr_t> unique;size_t count=0;for(const auto &owned:scene.boards){const auto &board=*owned;check(board.lifecycle.instances.empty()&&board.lifecycle.catalog.states.empty(),"continuation leaves no board-private concrete state copies");check(board.nesting.placements.size()==board.output.placements.size(),"native board strong owners match published geometry");for(const auto &p:board.nesting.placements){const auto index=size_t(p->instance18);check(scene.instances[index].owner08==&board.nesting&&scene.instances[index].current00.lock()==p&&scene.catalog->instances[index].placed&&scene.placementCatalog.states[index]==1,"same actual global instance belongs to the correct continued board");check(unique.insert(scene.sdkIdentities[index]).second,"continued global SDK identities are unique across all boards");++count;}}check(count+scene.unplaced.size()==scene.sdkIdentities.size(),"continued global demand is conserved");boards+=scene.boards.size();placements+=count;}
void prefix(const study::OrdinaryMultiPredefinedScene &old,const study::OrdinaryMultiPredefinedScene &current){check(current.boards.size()>=old.boards.size(),"continuation retains all original board occurrences");for(size_t n=0;n<old.boards.size();++n){const auto &source=*old.boards[n];const auto &board=*current.boards[n];check(board.source.sheetIdentity==source.source.sheetIdentity,"continued original sheet identity and order");for(size_t k=0;k<source.output.placements.size();++k){const auto &a=source.output.placements[k],&b=board.output.placements[k];check(a.group==b.group&&a.ordinal==b.ordinal&&a.poseIndex==b.poseIndex&&a.x==b.x&&a.y==b.y,"actual original placement pose survives global rebind and real native continuation");check(source.nesting.placements[k]!=board.nesting.placements[k]&&source.nesting.placements[k]->geometryOwner==board.nesting.placements[k]->geometryOwner,"independent placement properties reuse immutable geometry without mutating the original live scene");++preserved;}}}
template<class Fn>void rejects(Fn fn,int code){try{fn();throw std::runtime_error("expected multi continuation rejection");}catch(const study::Failure &failure){check(failure.code==code,"explicit multi continuation boundary");++cases;}}
}
int main(){using namespace study;try{
    {
        Input input;input.width=6;input.height=4;input.pitch=.5;input.parts={{{{0,0},{3,0},{3,2},{0,2}},{},{{0,false}},2}};OrdinaryMultiPredefinedSheet source{2000,6,4};source.predefined.records={manual(0,0,{0,0}),manual(0,1,{3,0})};Budget first(5.);auto original=ordinaryMultiPreNest(input,std::array{source},first);auto expanded=input;expanded.parts[0].quantity=8;std::vector<OrdinaryMultiAddedInstance> added;for(size_t n=2;n<8;++n)added.push_back({0,n,1000+n});const std::array stocks{OrdinaryMultiPredefinedSheet{2000,6,4},OrdinaryMultiPredefinedSheet{2001,6,4}};Budget more(20.);OrdinaryMultiContinuationTrace trace;auto result=ordinaryMultiNestMore(*original,expanded,added,stocks,offset(),more,&trace);
        check(result->unplaced.empty()&&result->boards.size()==2&&trace.globalCatalogBuilds==1&&trace.clonedOriginal==2&&trace.newBoards==1&&trace.added==6,"real global continuation fills original board then only the needed new physical stock");for(const auto &board:result->boards)check(valid_layout(expanded,board->output),"each actually continued board passes original material validation");prefix(*original,*result);native(*original);native(*result);++cases;
        auto duplicate=added;duplicate[0].sdkIdentity=1000;rejects([&]{Budget time(5.);ordinaryMultiNestMore(*original,expanded,duplicate,stocks,offset(),time);},PN2S_UNSUPPORTED);
        duplicate=added;duplicate[1].sdkIdentity=duplicate[0].sdkIdentity;rejects([&]{Budget time(5.);ordinaryMultiNestMore(*original,expanded,duplicate,stocks,offset(),time);},PN2S_UNSUPPORTED);
        auto changed=expanded;changed.parts[0].polygon[1].x=4;rejects([&]{Budget time(5.);ordinaryMultiNestMore(*original,changed,added,stocks,offset(),time);},PN2S_UNSUPPORTED);
        rejects([&]{Budget time(5.);ordinaryMultiNestMore(*original,expanded,std::span(added).first(1),stocks,offset(),time);},PN2S_INVALID);
    }
    {
        Input input;input.width=6;input.height=4;input.pitch=.5;input.parts={{{{0,0},{3,0},{3,2},{0,2}},{},{{0,false}},2}};std::array source{OrdinaryMultiPredefinedSheet{2100,6,4},OrdinaryMultiPredefinedSheet{2100,6,4}};source[0].predefined.records={manual(0,0,{0,0})};source[1].predefined.records={manual(0,1,{0,0})};Budget first(5.);auto original=ordinaryMultiPreNest(input,source,first);auto expanded=input;expanded.parts[0].quantity=8;std::vector<OrdinaryMultiAddedInstance> added;for(size_t n=2;n<8;++n)added.push_back({0,n,1000+n});Budget time(20.);auto result=ordinaryMultiNestMore(*original,expanded,added,{},offset(),time);check(result->unplaced.empty()&&result->boards.size()==2,"actual shared catalog completes residual material on two existing boards without acquiring stock");prefix(*original,*result);native(*result);++cases;
    }
    for(const bool reflected:{false,true}){
        Input input;input.width=24;input.height=16;input.pitch=.5;PartInput a;a.polygon={{7,-4},{11,-4},{11,-3},{8,-3},{8,-1},{7,-1}};a.pivot={8,-2};a.quantity=1;a.poses={{0,false},{90,false},{90,true}};PartInput b;b.polygon={{-3,5},{0,5},{0,7},{-3,7}};b.pivot={-1,6};b.quantity=1;b.poses=a.poses;input.parts={a,b};OrdinaryMultiPredefinedSheet sheet{2200,24,16};sheet.predefined.sheetOrigin={100,-50};sheet.predefined.records={manual(0,0,{106,-44},90,reflected),manual(1,0,{115,-40},90,reflected)};Budget first(5.);auto original=ordinaryMultiPreNest(input,std::array{sheet},first);auto expanded=input;expanded.parts[0].quantity=3;expanded.parts[1].quantity=3;const std::array added{OrdinaryMultiAddedInstance{0,1,1001},OrdinaryMultiAddedInstance{0,2,1002},OrdinaryMultiAddedInstance{1,1,1101},OrdinaryMultiAddedInstance{1,2,1102}};Budget time(20.);auto result=ordinaryMultiNestMore(*original,expanded,added,{},offset(),time);check(result->unplaced.empty()&&result->instanceBySdk.at(1100)!=original->instanceBySdk.at(1100),"adding earlier-group demand remaps later-group native indices while preserving concrete SDK identity");check(valid_layout(expanded,result->boards[0]->output),"shifted-pivot/reflected concave continuation has actual valid material");prefix(*original,*result);native(*original);native(*result);++cases;
    }
    {
        Input input;input.width=12;input.height=8;input.pitch=.5;input.parts={{{{0,0},{3,0},{3,2},{0,2}},{},{{0,false}},2}};OrdinaryMultiPredefinedSheet sheet{2300,12,8};sheet.predefined.records={manual(0,0,{-1,2}),manual(0,1,{-1,2})};Budget first(5.);auto original=ordinaryMultiPreNest(input,std::array{sheet},first);auto expanded=input;expanded.parts[0].quantity=4;const std::array added{OrdinaryMultiAddedInstance{0,2,1002},OrdinaryMultiAddedInstance{0,3,1003}};Budget time(20.);auto result=ordinaryMultiNestMore(*original,expanded,added,{},offset(),time);check(result->unplaced.empty()&&validatePredefinedContinuation(expanded,original->boards[0]->output,result->boards[0]->output).valid,"new material clears all real original manual defects while grandfathered prefix overlap/outside geometry remains");prefix(*original,*result);native(*result);++cases;
    }
    std::cout<<"{\"pass\":true,\"cases\":"<<cases<<",\"boardsInspected\":"<<boards<<",\"placementsInspected\":"<<placements<<",\"preservedOriginal\":"<<preserved<<",\"checks\":"<<checks<<"}\n";return 0;
}catch(const std::exception &error){std::cerr<<error.what()<<'\n';return 1;}}
